def initialize_memory_bank(path, **_extra):
    import json, os, datetime, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0493000" if __import__("os").path.isdir("./environment_mix/0493000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _op_log(memory_bank_id, operation_type, request_params, status, result_summary=None, error_message=None, started_at=None, completed_at=None, created_at=None):
        ops = _load("operations.json")
        ts = _now()
        row = {
            "id": _new_id("op"),
            "memory_bank_id": memory_bank_id,
            "operation_type": operation_type,
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result_summary": result_summary,
            "error_message": error_message,
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": created_at or ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    t0 = datetime.datetime.now(datetime.timezone.utc)
    created_op = _op_log(
        memory_bank_id=None,
        operation_type="initialize_memory_bank",
        request_params={"path": path},
        status="running",
        started_at=_now(),
    )

    try:
        if not isinstance(path, str):
            raise ValueError("path must be a string")
        raw = path.strip()
        if raw == "":
            raise ValueError("path must not be empty")

        # Resolve and validate path
        resolved = os.path.abspath(os.path.expanduser(raw))

        # Attempt to ensure directory exists
        try:
            os.makedirs(resolved, exist_ok=True)
        except (OSError, PermissionError) as e:
            # Vendor codes mention PERMISSION_DENIED/INVALID_ARGUMENT, but contract restricts error codes.
            # Map to UNAUTHORIZED for permission-like failures, VALIDATION_ERROR for malformed.
            end = _now()
            ops = _load("operations.json")
            for r in ops:
                if r.get("id") == created_op["id"]:
                    r["status"] = "failed"
                    r["error_message"] = f"Path not writable or cannot be created: {str(e)}"
                    r["completed_at"] = end
                    r["updated_at"] = end
                    break
            _save("operations.json", ops)
            return _err("UNAUTHORIZED", "Path not writable or cannot be created", path=resolved)

        # Try a real write test to validate writability
        test_file = os.path.join(resolved, ".memory_bank_write_test")
        try:
            with open(test_file, "w", encoding="utf-8") as f:
                f.write("ok")
            try:
                os.remove(test_file)
            except OSError:
                pass
        except (OSError, PermissionError) as e:
            end = _now()
            ops = _load("operations.json")
            for r in ops:
                if r.get("id") == created_op["id"]:
                    r["status"] = "failed"
                    r["error_message"] = f"Path not writable: {str(e)}"
                    r["completed_at"] = end
                    r["updated_at"] = end
                    break
            _save("operations.json", ops)
            return _err("UNAUTHORIZED", "Path not writable", path=resolved)

        banks = _load("memory_banks.json")
        existing = None
        for b in banks:
            if isinstance(b, dict) and b.get("root_path") == resolved:
                existing = b
                break

        ts = _now()
        created = False

        if existing is None:
            created = True
            bank_id = _new_id("mb")
            # uninitialized -> initializing -> ready
            bank = {
                "id": bank_id,
                "root_path": resolved,
                "status": "initializing",
                "current_mode": "ask",
                "active_context_file_id": None,
                "mcp_config": None,
                "last_error": None,
                "initialized_at": None,
                "created_at": ts,
                "updated_at": ts,
            }
            banks.append(bank)
            _save("memory_banks.json", banks)

            # complete initialization
            bank["status"] = "ready"
            bank["initialized_at"] = ts
            bank["updated_at"] = ts
            _save("memory_banks.json", banks)

            # Create baseline managed files (optional but consistent with "standard structure")
            files = _load("memory_bank_files.json")
            baseline = [
                ("active-context.md", "active-context.md"),
                ("decisions.md", "decisions.md"),
                ("progress.md", "progress.md"),
            ]
            for filename, rel in baseline:
                if any(f.get("memory_bank_id") == bank_id and f.get("relative_path") == rel for f in files if isinstance(f, dict)):
                    continue
                content = ""  # empty baseline
                sha = hashlib.sha256(content.encode("utf-8")).hexdigest()
                frow = {
                    "id": _new_id("mbf"),
                    "memory_bank_id": bank_id,
                    "filename": filename,
                    "relative_path": rel,
                    "content": content,
                    "content_sha256": sha,
                    "status": "active",
                    "naming_convention": "kebab-case" if "-" in filename else "unknown",
                    "last_read_at": None,
                    "last_written_at": ts,
                    "created_at": ts,
                    "updated_at": ts,
                }
                files.append(frow)
                if filename == "active-context.md":
                    bank["active_context_file_id"] = frow["id"]
            _save("memory_bank_files.json", files)
            _save("memory_banks.json", banks)

            result_summary = f"Initialized memory bank at {resolved}"
            mem_id = bank_id
        else:
            # Idempotent if already ready; if not ready, try legal transition to initializing then ready.
            mem_id = existing.get("id")
            if existing.get("status") == "ready":
                result_summary = f"Memory bank already exists at {resolved}"
            elif existing.get("status") in ("uninitialized", "error", "initializing"):
                # legal transitions: uninitialized->initializing; error->initializing; initializing->ready
                if existing.get("status") in ("uninitialized", "error"):
                    existing["status"] = "initializing"
                    existing["last_error"] = None
                    existing["updated_at"] = ts
                # finalize to ready
                existing["status"] = "ready"
                existing["initialized_at"] = existing.get("initialized_at") or ts
                existing["last_error"] = None
                existing["updated_at"] = ts
                _save("memory_banks.json", banks)
                result_summary = f"Re-initialized memory bank at {resolved}"
            elif existing.get("status") == "archived":
                end = _now()
                ops = _load("operations.json")
                for r in ops:
                    if r.get("id") == created_op["id"]:
                        r["status"] = "failed"
                        r["error_message"] = "Cannot initialize an archived memory bank"
                        r["completed_at"] = end
                        r["updated_at"] = end
                        break
                _save("operations.json", ops)
                return _err("INVALID_TRANSITION", "Cannot initialize an archived memory bank", root_path=resolved)
            else:
                end = _now()
                ops = _load("operations.json")
                for r in ops:
                    if r.get("id") == created_op["id"]:
                        r["status"] = "failed"
                        r["error_message"] = f"Unsupported status: {existing.get('status')}"
                        r["completed_at"] = end
                        r["updated_at"] = end
                        break
                _save("operations.json", ops)
                return _err("CONFLICT", "Unsupported memory bank status for initialization", status=existing.get("status"))

        # Persist "active context" selection via a small local state file (server-side context)
        state_path = os.path.join(_DB, "memory_bank_state.json")
        try:
            with open(state_path, encoding="utf-8") as f:
                state = json.load(f)
            if not isinstance(state, dict):
                state = {}
        except Exception:
            state = {}
        state["active_root_path"] = resolved
        state["active_memory_bank_id"] = mem_id
        state["updated_at"] = _now()
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2)

        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["memory_bank_id"] = mem_id
                r["status"] = "succeeded"
                r["result_summary"] = result_summary
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)

        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        return {
            "memory_bank": next((b for b in _load("memory_banks.json") if b.get("id") == mem_id), None),
            "resolved_root_path": resolved,
            "created": created,
            "operation": next((o for o in _load("operations.json") if o.get("id") == created_op["id"]), None),
            "latency_ms": latency_ms,
        }

    except ValueError as e:
        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["status"] = "failed"
                r["error_message"] = str(e)
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)
        return _err("VALIDATION_ERROR", str(e))
    except Exception as e:
        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["status"] = "failed"
                r["error_message"] = f"Internal error: {str(e)}"
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)
        return _err("CONFLICT", "Internal error", detail=str(e))

def set_memory_bank_path(path=None, **_extra):
    import json, os, datetime, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0493000" if __import__("os").path.isdir("./environment_mix/0493000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _op_log(memory_bank_id, operation_type, request_params, status, result_summary=None, error_message=None, started_at=None, completed_at=None):
        ops = _load("operations.json")
        ts = _now()
        row = {
            "id": _new_id("op"),
            "memory_bank_id": memory_bank_id,
            "operation_type": operation_type,
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result_summary": result_summary,
            "error_message": error_message,
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    created_op = _op_log(
        memory_bank_id=None,
        operation_type="set_memory_bank_path",
        request_params={"path": path},
        status="running",
        started_at=_now(),
    )

    try:
        if path is None:
            resolved = os.path.abspath(os.getcwd())
        else:
            if not isinstance(path, str):
                raise ValueError("path must be a string")
            raw = path.strip()
            if raw == "":
                raise ValueError("path must not be empty")
            resolved = os.path.abspath(os.path.expanduser(raw))

        if not os.path.exists(resolved) or not os.path.isdir(resolved):
            end = _now()
            ops = _load("operations.json")
            for r in ops:
                if r.get("id") == created_op["id"]:
                    r["status"] = "failed"
                    r["error_message"] = "Directory does not exist"
                    r["completed_at"] = end
                    r["updated_at"] = end
                    break
            _save("operations.json", ops)
            return _err("NOT_FOUND", "Directory does not exist", path=resolved)

        if not os.access(resolved, os.R_OK):
            end = _now()
            ops = _load("operations.json")
            for r in ops:
                if r.get("id") == created_op["id"]:
                    r["status"] = "failed"
                    r["error_message"] = "Directory not accessible"
                    r["completed_at"] = end
                    r["updated_at"] = end
                    break
            _save("operations.json", ops)
            return _err("UNAUTHORIZED", "Directory not accessible", path=resolved)

        banks = _load("memory_banks.json")
        bank = next((b for b in banks if isinstance(b, dict) and b.get("root_path") == resolved), None)

        # Set active context even if bank not yet initialized; callers may then call initialize.
        state_path = os.path.join(_DB, "memory_bank_state.json")
        try:
            with open(state_path, encoding="utf-8") as f:
                state = json.load(f)
            if not isinstance(state, dict):
                state = {}
        except Exception:
            state = {}
        state["active_root_path"] = resolved
        state["active_memory_bank_id"] = bank.get("id") if bank else None
        state["updated_at"] = _now()
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2)

        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["memory_bank_id"] = bank.get("id") if bank else None
                r["status"] = "succeeded"
                r["result_summary"] = f"Active memory bank path set to {resolved}"
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)

        return {
            "active_root_path": resolved,
            "active_memory_bank_id": bank.get("id") if bank else None,
            "memory_bank": bank,
            "operation": next((o for o in _load("operations.json") if o.get("id") == created_op["id"]), None),
        }

    except ValueError as e:
        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["status"] = "failed"
                r["error_message"] = str(e)
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)
        return _err("VALIDATION_ERROR", str(e))
    except Exception as e:
        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["status"] = "failed"
                r["error_message"] = f"Internal error: {str(e)}"
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)
        return _err("CONFLICT", "Internal error", detail=str(e))

def debug_mcp_config(verbose=None, **_extra):
    import json, os, datetime, uuid, platform

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0493000" if __import__("os").path.isdir("./environment_mix/0493000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _op_log(memory_bank_id, operation_type, request_params, status, result_summary=None, error_message=None, started_at=None, completed_at=None):
        ops = _load("operations.json")
        ts = _now()
        row = {
            "id": _new_id("op"),
            "memory_bank_id": memory_bank_id,
            "operation_type": operation_type,
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result_summary": result_summary,
            "error_message": error_message,
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    created_op = _op_log(
        memory_bank_id=None,
        operation_type="debug_mcp_config",
        request_params={"verbose": verbose},
        status="running",
        started_at=_now(),
    )

    try:
        if verbose is None:
            verbose_val = False
        else:
            if not isinstance(verbose, bool):
                raise ValueError("verbose must be a boolean")
            verbose_val = verbose

        # Load active selection state if present
        state_path = os.path.join(_DB, "memory_bank_state.json")
        try:
            with open(state_path, encoding="utf-8") as f:
                state = json.load(f)
            if not isinstance(state, dict):
                state = {}
        except Exception:
            state = {}

        active_root = state.get("active_root_path")
        active_id = state.get("active_memory_bank_id")

        bank = None
        if active_id:
            banks = _load("memory_banks.json")
            bank = next((b for b in banks if isinstance(b, dict) and b.get("id") == active_id), None)
        elif active_root:
            banks = _load("memory_banks.json")
            bank = next((b for b in banks if isinstance(b, dict) and b.get("root_path") == active_root), None)
            if bank:
                active_id = bank.get("id")

        cfg = {
            "service": "Memory Bank",
            "active_root_path": active_root,
            "active_memory_bank_id": active_id,
            "memory_bank_status": bank.get("status") if bank else None,
            "current_mode": bank.get("current_mode") if bank else None,
        }

        if verbose_val:
            cfg["diagnostics"] = {
                "cwd": os.getcwd(),
                "db_path": _DB,
                "state_file_present": os.path.exists(state_path),
                "platform": {
                    "python": platform.python_version(),
                    "system": platform.system(),
                    "release": platform.release(),
                },
                "environment_hints": {
                    "HOME": os.environ.get("HOME"),
                    "PWD": os.environ.get("PWD"),
                },
            }
            if bank:
                cfg["diagnostics"]["memory_bank_row"] = bank

        # Persist snapshot into bank.mcp_config if bank exists
        if bank:
            banks = _load("memory_banks.json")
            for b in banks:
                if isinstance(b, dict) and b.get("id") == bank.get("id"):
                    b["mcp_config"] = cfg
                    b["updated_at"] = _now()
                    bank = b
                    break
            _save("memory_banks.json", banks)

        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["memory_bank_id"] = active_id
                r["status"] = "succeeded"
                r["result_summary"] = "Returned MCP configuration"
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)

        return {
            "config": cfg,
            "operation": next((o for o in _load("operations.json") if o.get("id") == created_op["id"]), None),
        }

    except ValueError as e:
        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["status"] = "failed"
                r["error_message"] = str(e)
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)
        return _err("VALIDATION_ERROR", str(e))
    except Exception as e:
        end = _now()
        ops = _load("operations.json")
        for r in ops:
            if r.get("id") == created_op["id"]:
                r["status"] = "failed"
                r["error_message"] = f"Internal error: {str(e)}"
                r["completed_at"] = end
                r["updated_at"] = end
                break
        _save("operations.json", ops)
        return _err("CONFLICT", "Internal error", detail=str(e))

def read_memory_bank_file(filename, **_extra):
    import json, os, datetime, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0493000" if __import__("os").path.isdir("./environment_mix/0493000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _op_log(memory_bank_id, operation_type, request_params, status, result_summary=None, error_message=None, started_at=None, completed_at=None):
        ops = _load("operations.json")
        ts = _now()
        row = {
            "id": _new_id("op"),
            "memory_bank_id": memory_bank_id,
            "operation_type": operation_type,
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result_summary": result_summary,
            "error_message": error_message,
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    created_op = _op_log(
        memory_bank_id=None,
        operation_type="read_memory_bank_file",
        request_params={"filename": filename},
        status="running",
        started_at=_now(),
    )

    try:
        if not isinstance(filename, str):
            raise ValueError("filename must be a string")
        fn = filename.strip()
        if fn == "":
            raise ValueError("filename must not be empty")

        # Path traversal protection (relative_path is stored and compared literally)
        norm = fn.replace("\\", "/")
        if norm.startswith("/") or norm.startswith("../") or "/../" in norm or norm == ".." or "/./" in norm or norm.startswith("./"):
            end = _now()
            ops = _load("operations.json")
            for r in ops:
                if r.get("id") == created_op["id"]:
                    r["status"] = "failed"
                    r["error_message"] = "filename attempts path traversal or is not a simple relative path"
                    r["completed_at"] = end
                    r["updated_at"] = end
                    break
            _save("operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid filename", filename=filename)

        # Resolve selected memory bank context
        state_path = os.path.join(_DB, "memory_bank_state.json")
        try:
            with open(state_path, encoding="utf-8") as f:
                state = json.load(f)
            if not isinstance(state, dict):
                state = {}
        except Exception:
            state = {}

        active_id = state.get("active_memory_bank_id")
        active_root = state.get("active_root_path")

        banks = _load("memory_banks.json")
        bank = None
        if active_id:
            bank = next((b for b in banks if isinstance(b, dict) and b.get("id") == active_id), None)
        elif active_root:
            bank = next((b for b in banks if isinstance(b, dict) and b.get("root_path") == active_root), None)
            if bank:
                active_id = bank.get("id")

        if not bank:
            end = _now()
            ops = _load("operations.json")
            for r in ops:
                if r.get("id") == created_op["id"]:
                    r["status"] = "failed"
                    r["error_message"] = "No active memory bank selected"
                    r["completed_at"] = end
                    r["updated_at"] = end
                    break
            _save("operations.json", ops)
