        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ops = _load("operations.json")
    mbs = _load("memory_banks.json")
    files = _load("memory_bank_files.json")

    def _op_id():
        return f"op_{int(time.time()*1000)}_{os.urandom(4).hex()}"
    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"
    def _sha256(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()
    def _camel_case(s):
        return bool(re.search(r"[a-z][A-Z]", s)) and "-" not in s and "_" not in s
    def _detect_naming(s):
        if _camel_case(s):
            return "camelCase"
        if "-" in s:
            return "kebab-case"
        return "unknown"

    def _select_memory_bank():
        ready = [b for b in mbs if b.get("status") == "ready"]
        if ready:
            ready.sort(key=lambda r: r.get("updated_at") or r.get("created_at") or "")
            return ready[-1]
        non_arch = [b for b in mbs if b.get("status") != "archived"]
        if non_arch:
            non_arch.sort(key=lambda r: r.get("updated_at") or r.get("created_at") or "")
            return non_arch[-1]
        return None

    def _log_operation(memory_bank_id, status, request_params, result_summary=None, error_message=None, started_at=None, completed_at=None):
        op = {
            "id": _op_id(),
            "memory_bank_id": memory_bank_id,
            "operation_type": "update_active_context",
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result_summary": result_summary,
            "error_message": error_message,
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    def _validate_arr(name, v):
        if v is None:
            return None
        if not isinstance(v, list):
            return "must be an array of strings"
        for i, item in enumerate(v):
            if not isinstance(item, str):
                return f"item {i} must be a string"
        return None

    # Validate inputs
    for nm, v in (("tasks", tasks), ("issues", issues), ("nextSteps", nextSteps)):
        msg = _validate_arr(nm, v)
        if msg:
            op = _log_operation(None, "failed", {"tasks": tasks, "issues": issues, "nextSteps": nextSteps, "behavior": "partial_update"}, error_message=f"{nm} {msg}", started_at=now, completed_at=now)
            return _err("VALIDATION_ERROR", f"{nm} {msg}", operation_id=op["id"])

    mb = _select_memory_bank()
    if not mb:
        op = _log_operation(None, "failed", {"tasks": tasks, "issues": issues, "nextSteps": nextSteps, "behavior": "partial_update"}, error_message="No memory bank selected/available", started_at=now, completed_at=now)
        return _err("NOT_FOUND", "No memory bank selected/available", operation_id=op["id"])

    op = _log_operation(mb["id"], "running", {"tasks": tasks, "issues": issues, "nextSteps": nextSteps, "behavior": "partial_update"}, started_at=now)

    # Load existing state from file content if present (best-effort).
    # Behavior: partial update ("no change" when omitted); we persist a canonical rendered markdown.
    ac_file_id = mb.get("active_context_file_id")
    ac_file = None
    if ac_file_id:
        ac_file = next((f for f in files if f.get("id") == ac_file_id and f.get("memory_bank_id") == mb["id"]), None)

    if not ac_file:
        rel = "active-context.md"
        ac_file = next((f for f in files if f.get("memory_bank_id") == mb["id"] and f.get("relative_path") == rel), None)
        if not ac_file:
            ac_file = {
                "id": _new_id("mbf"),
                "memory_bank_id": mb["id"],
                "filename": "active-context.md",
                "relative_path": rel,
                "content": None,
                "content_sha256": None,
                "status": "active",
                "naming_convention": _detect_naming(rel),
                "last_read_at": None,
                "last_written_at": None,
                "created_at": now,
                "updated_at": now,
            }
            files.append(ac_file)
        mb["active_context_file_id"] = ac_file["id"]
        mb["updated_at"] = now

    # Best-effort parse old content for sections to preserve when fields omitted.
    def _extract_section(md, header):
        if not isinstance(md, str):
            return None
        lines = md.splitlines()
        try:
            idx = lines.index(header)
        except ValueError:
            return None
        items = []
        for ln in lines[idx + 1:]:
            if ln.startswith("## "):
                break
            ln = ln.strip()
            if ln.startswith("- "):
                items.append(ln[2:])
        return items

    old = ac_file.get("content")
    state = {
        "tasks": _extract_section(old, "## Tasks") or [],
        "issues": _extract_section(old, "## Issues") or [],
        "nextSteps": _extract_section(old, "## Next Steps") or [],
    }

    if tasks is not None:
        state["tasks"] = tasks
    if issues is not None:
        state["issues"] = issues
    if nextSteps is not None:
        state["nextSteps"] = nextSteps

    content = "# Active Context\n\n" + f"Last update: {now}\n\n"
    content += "## Tasks\n" + ("\n".join([f"- {x}" for x in state["tasks"]]) if state["tasks"] else "- (none)") + "\n\n"
    content += "## Issues\n" + ("\n".join([f"- {x}" for x in state["issues"]]) if state["issues"] else "- (none)") + "\n\n"
    content += "## Next Steps\n" + ("\n".join([f"- {x}" for x in state["nextSteps"]]) if state["nextSteps"] else "- (none)") + "\n"

    try:
        ac_file["filename"] = ac_file.get("filename") or "active-context.md"
        ac_file["relative_path"] = ac_file.get("relative_path") or "active-context.md"
        ac_file["content"] = content
        ac_file["content_sha256"] = _sha256(content)
        ac_file["status"] = "active"
        ac_file["naming_convention"] = ac_file.get("naming_convention") or _detect_naming(ac_file["relative_path"])
        ac_file["last_written_at"] = now
        ac_file["updated_at"] = now

        # Persist bank and files
        for i, b in enumerate(mbs):
            if b.get("id") == mb["id"]:
                mbs[i] = mb
                break
        _save("memory_banks.json", mbs)
        _save("memory_bank_files.json", files)

        op["status"] = "succeeded"
        op["result_summary"] = f"active context written ({ac_file['relative_path']})"
        op["completed_at"] = now
        op["updated_at"] = now
        for i, o in enumerate(ops):
            if o.get("id") == op["id"]:
                ops[i] = op
                break
        _save("operations.json", ops)

    except Exception as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        op["completed_at"] = now
        op["updated_at"] = now
        for i, o in enumerate(ops):
            if o.get("id") == op["id"]:
                ops[i] = op
                break
        _save("operations.json", ops)
        return _err("CONFLICT", "Active context file could not be written", operation_id=op["id"], details=str(e))

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation": {"id": op["id"], "status": op["status"], "latency_ms": latency_ms},
        "memory_bank_id": mb["id"],
        "active_context_file": {
            "id": ac_file["id"],
            "relative_path": ac_file["relative_path"],
            "content_sha256": ac_file["content_sha256"],
            "last_written_at": ac_file["last_written_at"],
        },
        "state": state,
    }

