            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    allowed = {"architect", "ask", "code", "debug", "test"}
    if not isinstance(mode, str) or mode not in allowed:
        op = _log_operation(None, "failed", {"mode": mode}, error_message="mode must be one of: architect, ask, code, debug, test", started_at=now, completed_at=now)
