def get_current_mode(**_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0493000" if __import__("os").path.isdir("./environment_mix/0493000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # load store
    memory_banks = _load("memory_banks.json")
    ops = _load("operations.json")

    def _new_id(prefix):
        # 18+ chars, uppercase A-Z0-9
        import secrets, string
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _log_op(status, memory_bank_id, req_params, result_summary=None, error_message=None):
        op = {
            "id": _new_id("op"),
            "memory_bank_id": memory_bank_id,
            "operation_type": "get_current_mode",
            "status": status,
            "request_params": req_params if isinstance(req_params, dict) else {},
            "result_summary": result_summary,
            "error_message": error_message,
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    # Resolve "selected" memory bank context: choose a usable one.
    # Prefer ready; else any non-archived; else none.
    selected = None
    for b in memory_banks:
        if b.get("status") == "ready":
            selected = b
            break
    if selected is None:
        for b in memory_banks:
            if b.get("status") in ("uninitialized", "initializing", "error"):
                selected = b
                break

    if selected is None:
        _log_op("failed", None, {}, error_message="No active memory bank/session available")
        return _err("NOT_FOUND", "No active mode/session available to report.")

    mode = selected.get("current_mode")
    if mode not in ("architect", "ask", "code", "debug", "test"):
        _log_op("failed", selected.get("id"), {}, error_message="Invalid current_mode stored")
        return _err("CONFLICT", "Stored current mode is invalid; memory bank record is inconsistent.")

    _log_op("succeeded", selected.get("id"), {}, result_summary=f"current_mode={mode}")
    return {
        "memory_bank_id": selected.get("id"),
        "mode": {"name": mode, "state": {}},
        "status": selected.get("status"),
        "updated_at": selected.get("updated_at"),
        "latency_ms": int((time.time() - t0) * 1000),
    }

