            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Defaults
    if dry_run is None:
        dry_run = False
    if force is None:
        force = False

    # Validate inputs
    if not isinstance(memory_bank_id, str):
        return _err("VALIDATION_ERROR", "memory_bank_id must be a string.")
    if not re.match(r"^mbk_[0-9A-Z]{18,}$", memory_bank_id):
        return _err("VALIDATION_ERROR", "memory_bank_id does not match required format ^mbk_[0-9A-Z]{18,}$.")
    if command_id is not None and not isinstance(command_id, str):
        return _err("VALIDATION_ERROR", "command_id must be a string if provided.")
    if not isinstance(dry_run, bool):
        return _err("VALIDATION_ERROR", "dry_run must be a boolean.")
    if not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean.")
    if notes is not None and not isinstance(notes, str):
        return _err("VALIDATION_ERROR", "notes must be a string if provided.")

    # Load datastore
    memory_banks = _load("memory_banks.json")
    progress_entries = _load("progress_entries.json")
    operations = _load("operations.json")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(20))

    # Find memory bank
    mb = None
    for r in memory_banks if isinstance(memory_banks, list) else []:
        if isinstance(r, dict) and r.get("id") == memory_bank_id:
            mb = r
            break
    if mb is None:
        # record failed op (observable dynamics)
        op_id = _new_id("op")
        op_row = {
            "id": op_id,
            "memory_bank_id": memory_bank_id,
            "operation_type": "complete_umb",
            "status": "failed",
            "request_params": {
                "memory_bank_id": memory_bank_id,
                "command_id": command_id,
                "dry_run": dry_run,
                "force": force,
                "notes": notes,
            },
            "result_summary": None,
            "error_message": "Memory bank not found.",
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        if not isinstance(operations, list):
            operations = []
        operations.append(op_row)
        _save("operations.json", operations)
        return _err("NOT_FOUND", "Memory bank not found.", operation_id=op_id, memory_bank_id=memory_bank_id)

    # Validate business rule: only succeed if selected memory bank is ready
    if mb.get("status") != "ready":
        op_id = _new_id("op")
        op_row = {
            "id": op_id,
            "memory_bank_id": memory_bank_id,
            "operation_type": "complete_umb",
            "status": "failed",
            "request_params": {
                "memory_bank_id": memory_bank_id,
                "command_id": command_id,
                "dry_run": dry_run,
                "force": force,
                "notes": notes,
            },
            "result_summary": None,
            "error_message": "Invalid state: memory bank must be in status='ready' to complete UMB.",
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        if not isinstance(operations, list):
            operations = []
        operations.append(op_row)
        _save("operations.json", operations)
        return _err(
            "INVALID_TRANSITION",
            "complete_umb requires memory bank status='ready' (business rule).",
            operation_id=op_id,
            memory_bank_id=memory_bank_id,
            status=mb.get("status"),
        )

    # If command_id is provided: accept if it matches an existing operations.id for this memory bank,
    # or if it is any identifier we can associate (some clients send non-op ids). Reject only if force=False
    # and it clearly refers to a different memory_bank_id in operations.
    command_assoc = None
    if command_id is not None:
        for op in operations if isinstance(operations, list) else []:
            if not isinstance(op, dict):
                continue
            if op.get("id") == command_id:
                command_assoc = op
                break
        if command_assoc is not None:
            if command_assoc.get("memory_bank_id") not in (None, memory_bank_id):
                if not force:
                    op_id = _new_id("op")
                    op_row = {
                        "id": op_id,
                        "memory_bank_id": memory_bank_id,
                        "operation_type": "complete_umb",
                        "status": "failed",
                        "request_params": {
                            "memory_bank_id": memory_bank_id,
                            "command_id": command_id,
                            "dry_run": dry_run,
                            "force": force,
                            "notes": notes,
                        },
                        "result_summary": None,
                        "error_message": "command_id refers to a different memory bank.",
                        "started_at": now,
                        "completed_at": now,
                        "created_at": now,
                        "updated_at": now,
                    }
                    if not isinstance(operations, list):
                        operations = []
                    operations.append(op_row)
                    _save("operations.json", operations)
                    return _err(
                        "VALIDATION_ERROR",
                        "command_id refers to a different memory bank (business rule). Use force=true to override.",
                        operation_id=op_id,
                        command_id=command_id,
                        memory_bank_id=memory_bank_id,
                        command_memory_bank_id=command_assoc.get("memory_bank_id"),
                    )
        else:
            # No matching op row; treat as opaque session id and allow (do not block valid calls).
            command_assoc = None

    # Create operation row and proceed
    op_id = _new_id("op")
    op_row = {
        "id": op_id,
        "memory_bank_id": memory_bank_id,
        "operation_type": "complete_umb",
        "status": "running",
        "request_params": {
            "memory_bank_id": memory_bank_id,
            "command_id": command_id,
            "dry_run": dry_run,
            "force": force,
            "notes": notes,
        },
        "result_summary": None,
        "error_message": None,
        "started_at": now,
        "completed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    if not isinstance(operations, list):
        operations = []
    operations.append(op_row)
    _save("operations.json", operations)

    # Determine pending progress entries deterministically: oldest recorded first
    pend = []
    for pe in progress_entries if isinstance(progress_entries, list) else []:
        if not isinstance(pe, dict):
            continue
        if pe.get("memory_bank_id") != memory_bank_id:
            continue
        if pe.get("status") == "recorded":
            pend.append(pe)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    pend.sort(key=lambda x: (_parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1), x.get("id") or ""))

    applied_ids = []
    failed_ids = []
    skipped_ids = []
    warnings = []

    # Apply: mark recorded -> applied (or failed if invalid row), unless dry_run
    any_changes = False
    for pe in pend:
        pe_id = pe.get("id")
        # Basic integrity checks: action/description non-empty
        if not isinstance(pe.get("action"), str) or pe.get("action").strip() == "":
            if dry_run:
                skipped_ids.append(pe_id)
                warnings.append(f"Would fail progress entry {pe_id}: missing action.")
                continue
            pe["status"] = "failed"
            pe["error_message"] = "Invalid progress entry: action is required."
            pe["updated_at"] = now
            failed_ids.append(pe_id)
            any_changes = True
            continue
        if not isinstance(pe.get("description"), str) or pe.get("description").strip() == "":
            if dry_run:
                skipped_ids.append(pe_id)
                warnings.append(f"Would fail progress entry {pe_id}: missing description.")
                continue
            pe["status"] = "failed"
            pe["error_message"] = "Invalid progress entry: description is required."
            pe["updated_at"] = now
            failed_ids.append(pe_id)
            any_changes = True
            continue

        # Legal transition recorded -> applied
        if dry_run:
            applied_ids.append(pe_id)
            continue

        pe["status"] = "applied"
        pe["error_message"] = None
        pe["updated_at"] = now
        applied_ids.append(pe_id)
        any_changes = True

    # If there were no pending entries and not dry_run, still succeed but no mutation => must still have effect?
    # The effect is recording the operation row; that's already persisted.
    # However, ensure we don't claim applied changes if none.
    summary_parts = []
    summary_parts.append(f"applied={len(applied_ids)}")
    summary_parts.append(f"failed={len(failed_ids)}")
    summary_parts.append(f"skipped={len(skipped_ids)}")
    if dry_run:
        summary_parts.append("dry_run=true")
    if notes:
        summary_parts.append("notes_attached=true")
    if command_id and command_assoc is None:
        warnings.append("command_id not found in operations; treated as opaque session identifier.")

    result_summary = "complete_umb: " + ", ".join(summary_parts)
    if warnings:
        # keep summary short, warnings in response
        pass

    # Persist mutations
    if not dry_run and any_changes:
        _save("progress_entries.json", progress_entries)

    # Update operation row to succeeded
    completed = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for op in operations:
        if isinstance(op, dict) and op.get("id") == op_id:
            op["status"] = "succeeded"
            op["result_summary"] = result_summary
            op["error_message"] = None
            op["completed_at"] = completed
            op["updated_at"] = completed
            break
    _save("operations.json", operations)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "operation": {
            "id": op_id,
            "memory_bank_id": memory_bank_id,
            "operation_type": "complete_umb",
            "status": "succeeded",
            "request_params": {
                "memory_bank_id": memory_bank_id,
                "command_id": command_id,
                "dry_run": dry_run,
                "force": force,
                "notes": notes,
            },
            "result_summary": result_summary,
            "started_at": now,
            "completed_at": completed,
        },
        "completion": {
            "memory_bank_id": memory_bank_id,
            "command_id": command_id,
            "dry_run": dry_run,
            "applied_progress_entry_ids": applied_ids,
            "failed_progress_entry_ids": failed_ids,
            "skipped_progress_entry_ids": skipped_ids,
            "warnings": warnings,
            "notes": notes,
        },
        "meta": {
            "latency_ms": latency_ms,
            "pending_before": len(pend),
        },
    }
